-- Title: iam get tenant context (S3 / EP-05 US-03 + US-04)
-- Kind: patch
-- Intent: iam_get_tenant_context
-- Touches: iam.get_tenant_context
-- Promoted from _drafts/009_iam_get_tenant_context.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function iam.get_tenant_context(p_tenant_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_role text;
  v_tenant_name text;
  v_permissions text[];
begin
  if v_user_id is null then
    raise exception 'not authenticated';
  end if;

  if p_tenant_id is null then
    return jsonb_build_object('status', 'none');
  end if;

  select m.role, t.name
  into v_role, v_tenant_name
  from iam.tenants t
  left join iam.memberships m
    on m.tenant_id = t.id
   and m.user_id = v_user_id
  where t.id = p_tenant_id;

  if not found then
    return jsonb_build_object(
      'status', 'invalidated',
      'invalidation_reason', 'accessDenied',
      'blocked_error_code', 'TENANT_ACCESS_DENIED',
      'tenant_id', p_tenant_id
    );
  end if;

  if v_role is null then
    return jsonb_build_object(
      'status', 'invalidated',
      'invalidation_reason', 'membershipRemoved',
      'blocked_error_code', 'MEMBERSHIP_REMOVED',
      'tenant_id', p_tenant_id,
      'tenant_name', v_tenant_name
    );
  end if;

  if v_role = 'owner' then
    v_permissions := array[]::text[];
  else
    select coalesce(array_agg(rp.permission order by rp.permission), array[]::text[])
    into v_permissions
    from iam.role_permissions rp
    where rp.role = v_role;
  end if;

  return jsonb_build_object(
    'status', 'valid',
    'user_id', v_user_id,
    'tenant_id', p_tenant_id,
    'tenant_name', v_tenant_name,
    'role', v_role,
    'permissions', to_jsonb(v_permissions)
  );
end;
$$;

revoke all on function iam.get_tenant_context(uuid) from public, anon;
grant execute on function iam.get_tenant_context(uuid) to authenticated;
